window.__texto({"id": "724715965", "paragrafos": [{"c": "identifica", "t": "PORTARIA CEPLAC/SDR/MAPA nº 269, DE 4 DE AGOSTO DE 2026"}, {"c": "ementa", "t": "Estabelece as diretrizes, os critérios e os procedimentos para concessão de bolsas vinculadas a atividades de pesquisa, desenvolvimento, inovação, difusão tecnológica, transferência de tecnologia e apoio técnico especializado, no âmbito da Comissão Executiva do Plano da Lavoura Cacaueira."}, {"c": "dou-paragraph", "t": "O DIRETOR DA COMISSÃO EXECUTIVA DO PLANO DA LAVOURA CACAUEIRA DA SECRETARIA DE DESENVOLVIMENTO RURAL DO MINSTÉRIO DA AGRICULTURA E PECUÁRIA, no uso das atribuições que lhe conferem o art. 35 e o art. 49 do Anexo I ao Decreto nº 12.642, de 1º de outubro de 2025, e tendo em vista o disposto na Lei nº 8.958, de 20 de dezembro de 1994, na Lei nº 10.973, de 2 de dezembro de 2004, na Lei nº 13.243, de 11 de janeiro de 2016, no Decreto nº 7.423, de 31 de dezembro de 2010, no Decreto nº 9.283, de 7 de fevereiro de 2018, na Portaria MAPA nº 462, de 26 de julho de 2022, e o que consta do Processo nº 21000.020163/2026-26, resolve:"}, {"c": "dou-paragraph", "t": "CAPÍTULO I"}, {"c": "dou-paragraph", "t": "DISPOSIÇÕES PRELIMINARES"}, {"c": "dou-paragraph", "t": "Art. 1º . Ficam estabelecidas, no âmbito da Comissão Executiva do Plano da Lavoura Cacaueira da Secretaria de Desenvolvimento Rural do Ministério da Agricultura e Pecuária, as diretrizes, os critérios e os procedimentos para concessão de bolsas vinculadas a atividades de pesquisa, desenvolvimento, inovação, difusão tecnológica, transferência de tecnologia e apoio técnico especializado."}, {"c": "dou-paragraph", "t": "Art. 2º As bolsas de que trata o art. 1º constituem instrumento de apoio à formação, capacitação, atração, valorização e fixação de pessoas qualificadas, bem como ao desenvolvimento de trajetórias acadêmicas, científicas, tecnológicas e profissionais vinculadas à missão institucional da Comissão Executiva do Plano da Lavoura Cacaueira - CEPLAC, para atuação nas seguintes atividades:"}, {"c": "dou-paragraph", "t": "I - pesquisa científica;"}, {"c": "dou-paragraph", "t": "II - desenvolvimento tecnológico;"}, {"c": "dou-paragraph", "t": "III - inovação;"}, {"c": "dou-paragraph", "t": "IV - difusão de tecnologia;"}, {"c": "dou-paragraph", "t": "V - extensão tecnológica;"}, {"c": "dou-paragraph", "t": "VI - proteção da propriedade intelectual;"}, {"c": "dou-paragraph", "t": "VII - transferência de tecnologia;"}, {"c": "dou-paragraph", "t": "VIII - gestão de projetos de PD&I; e"}, {"c": "dou-paragraph", "t": "IX - fortalecimento das cadeias produtivas relacionadas à missão institucional da CEPLAC."}, {"c": "dou-paragraph", "t": "Art. 3º A concessão de bolsas observará os princípios da legalidade, impessoalidade, moralidade, publicidade, eficiência, transparência, motivação, razoabilidade, proporcionalidade, segurança jurídica, mérito técnico-científico, interesse público e aderência às prioridades institucionais da CEPLAC."}, {"c": "dou-paragraph", "t": "Art. 4º As bolsas de que trata esta Portaria não geram vínculo empregatício, funcional, estatutário ou contratual de prestação de serviços com a CEPLAC, o Ministério da Agricultura e Pecuária, a fundação de apoio, a agência de fomento ou a instituição parceira, nem configuram contraprestação ordinária por serviços, bem como não poderão ser utilizadas para substituição de mão de obra permanente, suprimento de necessidade ordinária de pessoal ou execução de atividades desvinculadas do projeto aprovado."}, {"c": "dou-paragraph", "t": "Parágrafo único. A ausência de vínculo empregatício não afastará a necessidade de previsão, no plano de trabalho, no termo de outorga ou no instrumento jurídico aplicável, das condições mínimas necessárias à execução adequada e segura das atividades, especialmente quando envolverem atividades de campo, laboratório, deslocamentos ou exposição a riscos inerentes ao projeto."}, {"c": "dou-paragraph", "t": "Art. 5º A concessão de bolsas deverá estar vinculada a projeto, programa, plano de trabalho, acordo, convênio, termo de execução, instrumento de parceria ou iniciativa institucional formalmente aprovada pela autoridade competente, vedada a concessão dissociada de finalidade pública, objetivo técnico definido e previsão orçamentária compatível."}, {"c": "dou-paragraph", "t": "CAPÍTULO II"}, {"c": "dou-paragraph", "t": "DAS DEFINIÇÕES"}, {"c": "dou-paragraph", "t": "Art. 6º Para os fins desta Portaria, considera-se:"}, {"c": "dou-paragraph", "t": "I - bolsa: aporte financeiro concedido a pessoa física, sem caracterização de vínculo empregatício ou contraprestação ordinária de serviços, destinado ao apoio à formação, capacitação ou atuação qualificada em projeto, programa ou atividade institucional de pesquisa, desenvolvimento, inovação, difusão tecnológica, transferência de tecnologia, proteção da propriedade intelectual ou apoio técnico especializado;"}, {"c": "dou-paragraph", "t": "II - bolsa de estímulo à inovação: aporte de recursos financeiros concedido a pessoa física para execução de atividades de pesquisa científica e tecnológica, desenvolvimento de tecnologia, produto, processo ou serviço, extensão tecnológica, proteção da propriedade intelectual ou transferência de tecnologia, nos termos da Lei nº 10.973, de 2 de dezembro de 2004, e do Decreto nº 9.283, de 7 de fevereiro de 2018;"}, {"c": "dou-paragraph", "t": "III - bolsista: pessoa física selecionada para desenvolver atividades vinculadas a projeto, programa ou ação institucional da CEPLAC, conforme plano de trabalho, plano individual de atividades ou termo de outorga;"}, {"c": "dou-paragraph", "t": "IV - projeto de Pesquisa, Desenvolvimento e Inovação - PD&I: iniciativa formalmente estruturada, com objetivos, metas, cronograma, metodologia, resultados esperados, equipe, orçamento e instrumentos de acompanhamento definidos, voltada à geração, adaptação, validação, difusão ou aplicação de conhecimento científico, tecnológico ou inovador;"}, {"c": "dou-paragraph", "t": "V - difusão tecnológica: conjunto de ações destinadas à disseminação, validação, adaptação, demonstração, comunicação técnica e transferência de conhecimentos, tecnologias, práticas, processos ou soluções geradas ou apoiadas pela CEPLAC;"}, {"c": "dou-paragraph", "t": "VI - apoio técnico especializado: atividade técnico-instrumental, científica, tecnológica, administrativa especializada ou operacional qualificada, desde que indispensável e diretamente vinculada à execução, gestão técnica, monitoramento, sistematização, avaliação ou prestação de contas de projeto, programa ou ação institucional de pesquisa, desenvolvimento, inovação, difusão tecnológica ou transferência de tecnologia, vedada sua utilização para suprir atividades administrativas ordinárias ou permanentes da Administração;"}, {"c": "dou-paragraph", "t": "VII - fundação de apoio: fundação credenciada e autorizada nos termos da Lei nº 8.958, de 20 de dezembro de 1994, e do Decreto nº 7.423, de 31 de dezembro de 2010, apta a apoiar projetos de ensino, pesquisa, extensão, desenvolvimento institucional, científico, tecnológico e de estímulo à inovação de interesse da CEPLAC, quando cabível;"}, {"c": "dou-paragraph", "t": "VIII - agência de fomento: órgão ou entidade pública ou privada que tenha por finalidade apoiar, financiar ou fomentar ações de ciência, tecnologia, inovação, ensino, pesquisa, desenvolvimento ou extensão tecnológica;"}, {"c": "dou-paragraph", "t": "IX - Núcleo de Inovação Tecnológica - NIT: estrutura instituída pela CEPLAC responsável pela gestão da política institucional de inovação, nos termos da Lei nº 10.973, de 2 de dezembro de 2004, da Portaria CEPLAC nº 170, de 15 de agosto de 2022, e da Portaria CEPLAC nº 176, de 18 de agosto de 2022;"}, {"c": "dou-paragraph", "t": "X - termo de outorga: instrumento jurídico destinado à formalização da concessão de bolsa, contendo direitos, deveres, responsabilidades, vigência, valor, forma de acompanhamento, hipóteses de suspensão, cancelamento e restituição, quando cabível;"}, {"c": "dou-paragraph", "t": "XI - plano de trabalho: documento técnico que estrutura o projeto, o programa ou a ação institucional, contendo objetivos, justificativa, metas, atividades, cronograma, orçamento, equipe, modalidades de bolsas, perfis requeridos, critérios de seleção, resultados esperados e mecanismos de acompanhamento;"}, {"c": "dou-paragraph", "t": "XII - plano individual de atividades: documento vinculado ao termo de outorga, contendo o detalhamento das atividades atribuídas ao bolsista, carga horária ou regime de dedicação, entregas esperadas, cronograma, supervisor responsável e indicadores de acompanhamento;"}, {"c": "dou-paragraph", "t": "XIII - supervisor ou orientador: servidor, pesquisador, técnico ou responsável institucional formalmente designado para acompanhar, orientar e avaliar as atividades do bolsista no âmbito do projeto ou programa;"}, {"c": "dou-paragraph", "t": "XIV - unidade executora: unidade da CEPLAC responsável pela execução técnica do projeto, programa ou ação institucional a qual a bolsa esteja vinculada; e"}, {"c": "dou-paragraph", "t": "XV - instituição parceira: pessoa jurídica pública ou privada, nacional ou internacional, que participe, apoie ou coopere com a CEPLAC na execução de projeto, programa ou ação institucional, mediante instrumento formal próprio."}, {"c": "dou-paragraph", "t": "CAPÍTULO III"}, {"c": "dou-paragraph", "t": "DOS OBJETIVOS DA CONCESSÃO DE BOLSAS"}, {"c": "dou-paragraph", "t": "Art. 7º A concessão de bolsas no âmbito da CEPLAC tem por objetivos:"}, {"c": "dou-paragraph", "t": "I - fortalecer a capacidade institucional da CEPLAC em pesquisa científica, desenvolvimento tecnológico, inovação, difusão tecnológica e transferência de tecnologia;"}, {"c": "dou-paragraph", "t": "II - atrair, formar e reter talentos qualificados para atuação em projetos estratégicos relacionados à cacauicultura, sistemas agroflorestais, bioeconomia, sustentabilidade, agricultura tropical, qualidade de produtos, inovação produtiva, conservação de recursos genéticos e demais áreas finalísticas da CEPLAC;"}, {"c": "dou-paragraph", "t": "III - estimular a participação de estudantes, pesquisadores, profissionais técnicos, especialistas e colaboradores externos em projetos de interesse institucional;"}, {"c": "dou-paragraph", "t": "IV - apoiar a execução de projetos de PD&I, inclusive aqueles realizados em cooperação com instituições públicas, privadas, nacionais ou internacionais;"}, {"c": "dou-paragraph", "t": "V - contribuir para a proteção da propriedade intelectual, a gestão de ativos tecnológicos, a transferência de tecnologia e a inovação no ambiente produtivo;"}, {"c": "dou-paragraph", "t": "VI - ampliar a difusão de tecnologias, práticas sustentáveis, soluções produtivas e conhecimentos técnico-científicos gerados ou apoiados pela CEPLAC;"}, {"c": "dou-paragraph", "t": "VII - qualificar a gestão, o monitoramento, a sistematização e a avaliação de projetos estratégicos de pesquisa, desenvolvimento, inovação e difusão tecnológica; e"}, {"c": "dou-paragraph", "t": "VIII - fortalecer a presença institucional da CEPLAC como referência nacional e internacional em ciência, tecnologia e inovação aplicada à cacauicultura, aos sistemas agroflorestais e às cadeias produtivas sustentáveis."}, {"c": "dou-paragraph", "t": "CAPÍTULO IV"}, {"c": "dou-paragraph", "t": "DO CAMPO DE APLICAÇÃO"}, {"c": "dou-paragraph", "t": "Art. 8º Esta Portaria aplica-se às unidades centrais, regionais, centros de desenvolvimento, unidades de pesquisa, inovação, difusão tecnológica, laboratórios, campos experimentais e demais estruturas da CEPLAC envolvidas na formulação, execução, acompanhamento ou avaliação de projetos, programas ou ações que prevejam concessão de bolsas."}, {"c": "dou-paragraph", "t": "Art. 9º As bolsas de que trata esta Portaria poderão ser concedidas no âmbito de:"}, {"c": "dou-paragraph", "t": "I - projetos de pesquisa científica e tecnológica;"}, {"c": "dou-paragraph", "t": "II - projetos de desenvolvimento tecnológico;"}, {"c": "dou-paragraph", "t": "III - projetos de inovação;"}, {"c": "dou-paragraph", "t": "IV - projetos de difusão tecnológica e transferência de tecnologia;"}, {"c": "dou-paragraph", "t": "V - ações de proteção, gestão e exploração de propriedade intelectual;"}, {"c": "dou-paragraph", "t": "VI - programas de formação e capacitação técnico-científica;"}, {"c": "dou-paragraph", "t": "VII - ações de apoio técnico especializado à execução e gestão de projetos;"}, {"c": "dou-paragraph", "t": "VIII - projetos de cooperação técnica nacional ou internacional;"}, {"c": "dou-paragraph", "t": "IX - atividades de validação, adaptação, demonstração ou disseminação de tecnologias; e"}, {"c": "dou-paragraph", "t": "X - programas institucionais estratégicos aprovados pela Diretoria da CEPLAC."}, {"c": "dou-paragraph", "t": "CAPÍTULO V"}, {"c": "dou-paragraph", "t": "DAS MODALIDADES DE BOLSAS"}, {"c": "dou-paragraph", "t": "Art. 10. As bolsas previstas nesta Portaria poderão ser concedidas nas seguintes modalidades, observadas a natureza do projeto, a complexidade das atividades, a titulação ou experiência exigida, a disponibilidade orçamentária e os critérios definidos em instrumento específico:"}, {"c": "dou-paragraph", "t": "I - Bolsa de Iniciação Científica, Tecnológica ou de Inovação - destinada a estudantes de nível médio técnico, graduação ou cursos correlatos, para participação em atividades de iniciação à pesquisa, desenvolvimento tecnológico, inovação, difusão tecnológica ou apoio técnico supervisionado;"}, {"c": "dou-paragraph", "t": "II - Bolsa de Apoio Técnico - destinada a profissionais de nível médio, técnico ou superior, com formação ou experiência compatível com as atividades de apoio à execução de projetos, laboratórios, campos experimentais, ações de difusão, coleta e sistematização de dados, atividades de campo, processamento de informações ou suporte técnico-operacional, desde que essas atividades estejam diretamente vinculadas ao objeto técnico do projeto e não configurem substituição de mão de obra permanente ou atividade administrativa ordinária;"}, {"c": "dou-paragraph", "t": "III - Bolsa de Desenvolvimento Tecnológico e Inovação - destinada a profissionais de nível superior, especialistas, mestres ou doutores, com experiência compatível com atividades de pesquisa, desenvolvimento, inovação, validação tecnológica, transferência de tecnologia ou solução de desafios técnico-científicos;"}, {"c": "dou-paragraph", "t": "IV - Bolsa de Especialista Visitante - destinada a profissional de reconhecida experiência técnica, científica, tecnológica, produtiva, gerencial ou institucional, cuja atuação temporária seja necessária para complementar competências da equipe executora do projeto;"}, {"c": "dou-paragraph", "t": "V - Bolsa de Difusão Tecnológica e Extensão Inovadora - destinada a profissionais que atuem na disseminação, validação, adaptação, comunicação técnica, demonstração, capacitação, extensão tecnológica ou transferência de tecnologias, práticas, processos ou soluções relacionadas às finalidades institucionais da CEPLAC;"}, {"c": "dou-paragraph", "t": "VI - Bolsa de Tecnologia da Informação, Dados e Sistemas - destinada a profissionais envolvidos em atividades de desenvolvimento, implantação, manutenção, análise, modelagem, gestão de dados, inteligência digital, sistemas de informação, plataformas tecnológicas ou soluções digitais vinculadas a projetos institucionais de pesquisa, desenvolvimento, inovação, difusão tecnológica, transferência de tecnologia ou gestão de ativos tecnológicos, vedada a utilização da bolsa para manutenção ordinária de sistemas administrativos desvinculados de projeto aprovado;"}, {"c": "dou-paragraph", "t": "VII - Bolsa de Apoio à Gestão de Projetos de PD&I - destinada a profissionais que atuem em atividades técnico-especializadas de planejamento, organização, monitoramento, sistematização, gestão de informações, acompanhamento de cronogramas, apoio à elaboração de relatórios, indicadores, prestação de contas técnica e avaliação de resultados de projetos, desde que as atividades sejam especializadas, temporárias, vinculadas ao projeto aprovado e que não se confundam com atribuições administrativas permanentes da CEPLAC ou do Ministério da Agricultura e Pecuária;"}, {"c": "dou-paragraph", "t": "VIII - Bolsa de Pesquisador Visitante ou Pesquisador Sênior - destinada a profissional de elevada qualificação, trajetória reconhecida e experiência relevante na coordenação, execução ou consolidação de projetos científicos, tecnológicos ou de inovação de interesse estratégico da CEPLAC; e"}, {"c": "dou-paragraph", "t": "IX - outras modalidades que venham a ser instituídas por ato específico da Diretoria da CEPLAC, desde que compatíveis com a legislação aplicável e com os objetivos desta Portaria."}, {"c": "dou-paragraph", "t": "§ 1º A criação, adaptação ou utilização de modalidades de bolsas deverá observar a natureza das atividades, o nível de complexidade técnica, a titulação ou experiência requerida, a disponibilidade orçamentária e a aderência aos objetivos do projeto."}, {"c": "dou-paragraph", "t": "§ 2º As modalidades, níveis e valores de bolsas poderão adotar, como referência, tabelas de agências oficiais de fomento ou de instituições públicas congêneres, sem vinculação automática, sem prejuízo da definição de parâmetros próprios pela CEPLAC, mediante ato fundamentado da autoridade competente."}, {"c": "dou-paragraph", "t": "§ 3º O enquadramento do bolsista em modalidade ou nível específico deverá ser motivado tecnicamente, com base na formação, na experiência, na complexidade das atividades, nas responsabilidades atribuídas, na carga horária ou no regime de dedicação e resultados esperados."}, {"c": "dou-paragraph", "t": "CAPÍTULO VI"}, {"c": "dou-paragraph", "t": "DOS REQUISITOS PARA CONCESSÃO"}, {"c": "dou-paragraph", "t": "Art. 11. A concessão de bolsas dependerá da existência cumulativa dos seguintes requisitos:"}, {"c": "dou-paragraph", "t": "I - projeto, programa, plano de trabalho ou ação institucional formalmente aprovado;"}, {"c": "dou-paragraph", "t": "II - previsão expressa da bolsa no plano de trabalho, no instrumento de parceria, no projeto aprovado ou em documento técnico equivalente;"}, {"c": "dou-paragraph", "t": "III - justificativa técnica quanto à necessidade da bolsa para execução do projeto ou atividade;"}, {"c": "dou-paragraph", "t": "IV - definição da modalidade, nível, valor, vigência, carga horária ou regime de dedicação;"}, {"c": "dou-paragraph", "t": "V - descrição das atividades a serem desempenhadas pelo bolsista;"}, {"c": "dou-paragraph", "t": "VI - indicação do supervisor ou orientador responsável;"}, {"c": "dou-paragraph", "t": "VII - disponibilidade orçamentária e financeira;"}, {"c": "dou-paragraph", "t": "VIII - definição de critérios objetivos de seleção ou justificativa técnica para hipótese excepcional de seleção específica, quando admitida;"}, {"c": "dou-paragraph", "t": "IX - formalização por termo de outorga ou instrumento equivalente; e"}, {"c": "dou-paragraph", "t": "X - observância das normas de transparência, acompanhamento, prestação de contas e registro documental."}, {"c": "dou-paragraph", "t": "Art. 12. O plano de trabalho ou documento equivalente deverá conter, sempre que aplicável:"}, {"c": "dou-paragraph", "t": "I - a identificação do projeto ou programa;"}, {"c": "dou-paragraph", "t": "II - os objetivos gerais e específicos;"}, {"c": "dou-paragraph", "t": "III - a justificativa institucional;"}, {"c": "dou-paragraph", "t": "IV - as metas e resultados esperados;"}, {"c": "dou-paragraph", "t": "V - as atividades a serem desenvolvidas;"}, {"c": "dou-paragraph", "t": "VI - o cronograma de execução;"}, {"c": "dou-paragraph", "t": "VII - a equipe responsável;"}, {"c": "dou-paragraph", "t": "VIII - as modalidades, os quantitativos, os valores e a vigência das bolsas;"}, {"c": "dou-paragraph", "t": "IX - os perfis, os requisitos mínimos e os critérios de seleção dos bolsistas;"}, {"c": "dou-paragraph", "t": "X - a fonte de recursos;"}, {"c": "dou-paragraph", "t": "XI - a responsabilidades da CEPLAC, da fundação de apoio, da agência de fomento, da instituição parceira e do bolsista, conforme o caso;"}, {"c": "dou-paragraph", "t": "XII - a forma de acompanhamento, avaliação e entrega de relatórios; e"}, {"c": "dou-paragraph", "t": "XIII - a previsão de despesas necessárias à execução das atividades, inclusive deslocamentos, passagens, hospedagem, alimentação em campo, seguro, equipamentos de proteção individual e outros itens indispensáveis, quando cabíveis."}, {"c": "dou-paragraph", "t": "CAPÍTULO VII"}, {"c": "dou-paragraph", "t": "DA SELEÇÃO DOS BOLSISTAS"}, {"c": "dou-paragraph", "t": "Art. 13. A seleção de bolsistas deverá observar critérios objetivos, transparentes, impessoais e previamente definidos, compatíveis com a natureza da bolsa, a complexidade das atividades e os objetivos do projeto."}, {"c": "dou-paragraph", "t": "Art. 14. A seleção de bolsistas poderá ocorrer por meio de:"}, {"c": "dou-paragraph", "t": "I - chamada pública;"}, {"c": "dou-paragraph", "t": "II - edital específico;"}, {"c": "dou-paragraph", "t": "III - processo seletivo simplificado;"}, {"c": "dou-paragraph", "t": "IV - banco de talentos ou cadastro previamente constituído; e"}, {"c": "dou-paragraph", "t": "V - seleção específica mediante justificativa técnica individualizada e fundamentada, em caráter excepcional, quando a natureza singular da atividade, a especialização requerida, a continuidade técnica do projeto ou a existência de profissional com experiência prévia diretamente vinculada ao objeto demonstrar, de forma motivada, a inadequação ou inconveniência de seleção ampla, desde que comprovada a compatibilidade do perfil selecionado com as atividades previstas e preservados os princípios da impessoalidade, moralidade, motivação, transparência, isonomia e interesse público."}, {"c": "dou-paragraph", "t": "§ 1º A chamada pública, o edital ou o processo seletivo simplificado deverão conter, no mínimo:"}, {"c": "dou-paragraph", "t": "I - a identificação do projeto;"}, {"c": "dou-paragraph", "t": "II - o número de vagas;"}, {"c": "dou-paragraph", "t": "III - a modalidade da bolsa;"}, {"c": "dou-paragraph", "t": "IV - o valor;"}, {"c": "dou-paragraph", "t": "V - a vigência;"}, {"c": "dou-paragraph", "t": "VI - os requisitos mínimos;"}, {"c": "dou-paragraph", "t": "VII - as atividades previstas;"}, {"c": "dou-paragraph", "t": "VIII - os critérios de avaliação;"}, {"c": "dou-paragraph", "t": "IX - a forma de inscrição;"}, {"c": "dou-paragraph", "t": "X - os documentos exigidos;"}, {"c": "dou-paragraph", "t": "XI - as etapas de seleção;"}, {"c": "dou-paragraph", "t": "XII - os prazos para recurso; e"}, {"c": "dou-paragraph", "t": "XIII - o resultado final e a forma de convocação."}, {"c": "dou-paragraph", "t": "§ 2º A seleção específica de que trata o inciso V do caput deverá ser motivada em documento próprio, com demonstração da compatibilidade entre o perfil selecionado, as atividades a serem executadas, a necessidade do projeto e o interesse institucional."}, {"c": "dou-paragraph", "t": "§ 3º A adoção de procedimento excepcional não afasta a necessidade de comprovação documental dos requisitos de formação, experiência, regularidade e aderência técnica do bolsista às atividades previstas."}, {"c": "dou-paragraph", "t": "§ 4º A seleção específica prevista no inciso V do caput deverá ser instruída com justificativa técnica individualizada, currículo do selecionado, comprovação dos requisitos exigidos, manifestação do supervisor ou responsável técnico e aprovação da autoridade competente da unidade executora, sem prejuízo do registro nos autos do processo administrativo."}, {"c": "dou-paragraph", "t": "§ 5º É vedada a seleção, concessão ou manutenção de bolsa em situação que configure nepotismo, conflito de interesses, favorecimento pessoal, direcionamento indevido ou violação aos princípios da impessoalidade, moralidade e isonomia, devendo eventual vínculo pessoal, profissional, societário ou familiar relevante ser declarado e avaliado nos autos."}, {"c": "dou-paragraph", "t": "Art. 15. Os critérios de seleção poderão considerar, conforme a modalidade da bolsa:"}, {"c": "dou-paragraph", "t": "I - a formação acadêmica ou técnica;"}, {"c": "dou-paragraph", "t": "II - a experiência profissional;"}, {"c": "dou-paragraph", "t": "III - a experiência em pesquisa, desenvolvimento, inovação, difusão tecnológica, extensão, gestão de projetos ou áreas correlatas;"}, {"c": "dou-paragraph", "t": "IV - a produção técnico-científica;"}, {"c": "dou-paragraph", "t": "V - o domínio de metodologias, ferramentas, sistemas ou técnicas específicas;"}, {"c": "dou-paragraph", "t": "VI - a aderência do currículo às atividades previstas;"}, {"c": "dou-paragraph", "t": "VII - o desempenho em entrevista, prova, análise curricular, análise documental, plano de trabalho ou memorial técnico;"}, {"c": "dou-paragraph", "t": "VIII - a disponibilidade para cumprimento da carga horária ou regime de dedicação;"}, {"c": "dou-paragraph", "t": "IX - a experiência em atividades de campo, laboratório, comunidades rurais, sistemas agroflorestais, cacauicultura, bioeconomia, qualidade de produtos, inovação produtiva ou temas correlatos, quando pertinente; ou"}, {"c": "dou-paragraph", "t": "X - outros critérios tecnicamente justificados no instrumento de seleção."}, {"c": "dou-paragraph", "t": "Parágrafo único. Sempre que possível, os critérios de que trata o caput deverão ser acompanhados de pesos, pontuação ou parâmetros de avaliação, a fim de reduzir subjetividade e assegurar isonomia entre os candidatos."}, {"c": "dou-paragraph", "t": "Art. 16. A seleção deverá ser conduzida pela unidade executora do projeto, com participação do supervisor ou pesquisador responsável e, quando cabível, de comissão avaliadora a ser designada para essa finalidade."}, {"c": "dou-paragraph", "t": "§ 1º Quando a bolsa for operacionalizada por fundação de apoio, agência de fomento ou instituição parceira, caberá ao instrumento jurídico respectivo definir as atribuições de cada partícipe na seleção, convocação, formalização, pagamento, acompanhamento e encerramento da bolsa."}, {"c": "dou-paragraph", "t": "§ 2º A fundação de apoio poderá realizar atos operacionais de inscrição, recebimento documental, pagamento, gestão administrativa e formalização dos bolsistas, sem prejuízo da responsabilidade técnica da CEPLAC quanto à definição perfil, dos critérios, da necessidade institucional e do acompanhamento das atividades."}, {"c": "dou-paragraph", "t": "§ 3º O processo seletivo deverá ser documentado nos autos do processo administrativo correspondente, com o registro dos critérios adotados, os candidatos avaliados, o resultado, eventuais recursos e decisão final."}, {"c": "dou-paragraph", "t": "CAPÍTULO VIII"}, {"c": "dou-paragraph", "t": "DOS VALORES, DA VIGÊNCIA E DA CARGA HORÁRIA"}, {"c": "dou-paragraph", "t": "Art. 17. Os valores das bolsas serão definidos em função da modalidade, do nível de complexidade das atividades, da titulação, da experiência, da carga horária ou regime de dedicação, da disponibilidade orçamentária e das referências adotadas pela CEPLAC."}, {"c": "dou-paragraph", "t": "§ 1º A CEPLAC poderá adotar como referência tabelas de valores de bolsas praticadas por agências oficiais de fomento ou instituições públicas congêneres, sem vinculação automática, observadas as peculiaridades do projeto, a complexidade das atividades e a disponibilidade orçamentária."}, {"c": "dou-paragraph", "t": "§ 2º Os valores das bolsas serão definidos em tabela de referência aprovada em ato próprio pela autoridade competente, instruído com justificativa técnica, indicação das referências utilizadas, disponibilidade orçamentária e compatibilidade com a natureza, a complexidade e a duração das atividades previstas no projeto."}, {"c": "dou-paragraph", "t": "§ 3º A atualização dos valores poderá considerar a revisão das tabelas de referência de agências oficiais de fomento, a complexidade das atividades, a disponibilidade orçamentária, a necessidade de atração e retenção de profissionais qualificados e a preservação da capacidade institucional de execução dos projetos."}, {"c": "dou-paragraph", "t": "Art. 18. A vigência da bolsa deverá ser compatível com o cronograma do projeto ou atividade, não podendo ultrapassar a vigência do instrumento que lhe dá suporte, salvo prorrogação formal e justificada."}, {"c": "dou-paragraph", "t": "§ 1º A bolsa poderá ser concedida pelo período mínimo de um mês e pelo período máximo previsto no projeto, programa, plano de trabalho, edital, chamada pública, termo de outorga ou instrumento de parceria."}, {"c": "dou-paragraph", "t": "§ 2º A prorrogação da bolsa dependerá de justificativa técnica, avaliação satisfatória do desempenho do bolsista, disponibilidade orçamentária e manutenção do interesse institucional."}, {"c": "dou-paragraph", "t": "Art. 19. O regime de dedicação do bolsista deverá ser compatível com a modalidade da bolsa, a natureza das atividades, o cronograma do projeto e os resultados esperados, e será definido no instrumento de seleção, no plano individual de atividades ou no termo de outorga."}, {"c": "dou-paragraph", "t": "§ 1º As bolsas de iniciação científica, tecnológica ou de inovação poderão prever regime de dedicação parcial, compatível com a condição acadêmica do bolsista e com as atividades supervisionadas previstas no projeto."}, {"c": "dou-paragraph", "t": "§ 2º As demais modalidades poderão prever regime de dedicação compatível com a complexidade técnica das atividades, com as entregas pactuadas e com a disponibilidade exigida para a adequada execução do projeto."}, {"c": "dou-paragraph", "t": "§ 3º Quando necessário, o instrumento de seleção, o plano individual de atividades ou o termo de outorga poderá indicar carga horária referencial, exclusivamente para fins de organização, acompanhamento e compatibilização das atividades do projeto."}, {"c": "dou-paragraph", "t": "§ 4º A definição de regime de dedicação ou de carga horária referencial não caracteriza vínculo empregatício, subordinação trabalhista, controle funcional de jornada, exclusividade funcional ou prestação ordinária de serviços, e destina-se exclusivamente à organização técnica, ao acompanhamento das entregas e à compatibilização das atividades vinculadas ao projeto."}, {"c": "dou-paragraph", "t": "CAPÍTULO IX"}, {"c": "dou-paragraph", "t": "DA FORMALIZAÇÃO DA BOLSA"}, {"c": "dou-paragraph", "t": "Art. 20. A concessão da bolsa será formalizada mediante termo de outorga ou instrumento equivalente, a ser celebrado entre o bolsista e a instituição concedente ou gestora dos recursos, conforme previsto no projeto, instrumento de parceria ou plano de trabalho."}, {"c": "dou-paragraph", "t": "Art. 21. O termo de outorga deverá conter, no mínimo:"}, {"c": "dou-paragraph", "t": "I - a identificação do bolsista;"}, {"c": "dou-paragraph", "t": "II - a identificação do projeto, programa ou ação institucional;"}, {"c": "dou-paragraph", "t": "III - a modalidade, o nível, o valor e a vigência da bolsa;"}, {"c": "dou-paragraph", "t": "IV - a fonte dos recursos;"}, {"c": "dou-paragraph", "t": "V - o plano individual de atividades;"}, {"c": "dou-paragraph", "t": "VI - a carga horária ou regime de dedicação;"}, {"c": "dou-paragraph", "t": "VII - o supervisor ou orientador responsável;"}, {"c": "dou-paragraph", "t": "VIII - os direitos, os deveres e as responsabilidades do bolsista;"}, {"c": "dou-paragraph", "t": "IX - as regras de confidencialidade, propriedade intelectual e uso de informações;"}, {"c": "dou-paragraph", "t": "X - a forma de acompanhamento e apresentação de relatórios;"}, {"c": "dou-paragraph", "t": "XI - as hipóteses de suspensão, cancelamento, substituição ou encerramento;"}, {"c": "dou-paragraph", "t": "XII - as regras de restituição de valores, quando cabível;"}, {"c": "dou-paragraph", "t": "XIII - a autorização para tratamento de dados pessoais estritamente necessários à gestão da bolsa, observada a legislação aplicável;"}, {"c": "dou-paragraph", "t": "XIV - a declaração de ciência quanto à inexistência de vínculo empregatício, funcional, estatutário ou contratual de prestação de serviços;"}, {"c": "dou-paragraph", "t": "XV - a declaração sobre eventual acumulação de bolsas, vínculo funcional, conflito de interesses, parentesco ou situação que possa comprometer a impessoalidade da concessão; e"}, {"c": "dou-paragraph", "t": "XVI - o foro ou instância administrativa competente para dirimir dúvidas, quando aplicável."}, {"c": "dou-paragraph", "t": "Art. 22. O bolsista deverá apresentar, antes da formalização da bolsa, os documentos exigidos no instrumento de seleção ou no termo de outorga, podendo ser solicitado, conforme o caso:"}, {"c": "dou-paragraph", "t": "I - documento de identificação;"}, {"c": "dou-paragraph", "t": "II - Cadastro de Pessoas Físicas - CPF;"}, {"c": "dou-paragraph", "t": "III - comprovante de residência;"}, {"c": "dou-paragraph", "t": "IV - currículo atualizado, preferencialmente na Plataforma Lattes, quando aplicável;"}, {"c": "dou-paragraph", "t": "V - comprovantes de formação, titulação e experiência;"}, {"c": "dou-paragraph", "t": "VI - comprovante de matrícula, quando estudante;"}, {"c": "dou-paragraph", "t": "VII - dados bancários;"}, {"c": "dou-paragraph", "t": "VIII - declaração de não acúmulo indevido de bolsas;"}, {"c": "dou-paragraph", "t": "IX - declaração de disponibilidade para execução das atividades;"}, {"c": "dou-paragraph", "t": "X - termo de confidencialidade, quando cabível; e"}, {"c": "dou-paragraph", "t": "XI - outros documentos necessários à regular formalização da bolsa."}, {"c": "dou-paragraph", "t": "CAPÍTULO X"}, {"c": "dou-paragraph", "t": "DAS CONDIÇÕES DE EXECUÇÃO DAS ATIVIDADES E DAS PREVISÕES APLICÁVEIS AO BOLSISTA"}, {"c": "dou-paragraph", "t": "Art. 23. Poderão ser asseguradas aos bolsistas, conforme a natureza da bolsa, do plano de trabalho, do termo de outorga, do instrumento jurídico aplicável e da disponibilidade orçamentária do projeto, as seguintes condições, necessárias à execução adequada das atividades:"}, {"c": "dou-paragraph", "t": "I - recebimento da bolsa no valor, forma e periodicidade estabelecidos no termo de outorga;"}, {"c": "dou-paragraph", "t": "II - acesso às informações necessárias ao adequado desenvolvimento das atividades;"}, {"c": "dou-paragraph", "t": "III - orientação e acompanhamento por supervisor ou responsável técnico;"}, {"c": "dou-paragraph", "t": "IV - condições adequadas para execução das atividades previstas;"}, {"c": "dou-paragraph", "t": "V - fornecimento de equipamentos de proteção individual, quando exigidos pela natureza da atividade;"}, {"c": "dou-paragraph", "t": "VI - custeio ou ressarcimento de despesas previamente autorizadas e diretamente vinculadas à execução do projeto, a exemplo de deslocamentos, passagens, hospedagem, alimentação em campo, ajuda de custo ou outras despesas operacionais, quando previstas no plano de trabalho ou no instrumento jurídico aplicável;"}, {"c": "dou-paragraph", "t": "VII - seguro contra acidentes pessoais, quando as atividades envolverem campo, laboratório, deslocamento, risco operacional ou outra situação que justifique a cobertura;"}, {"c": "dou-paragraph", "t": "VIII - possibilidade de suspensão temporária, adequação ou prorrogação de vigência da bolsa por motivo de saúde, mediante apresentação de documentação comprobatória, desde que compatível com o cronograma do projeto, com a disponibilidade orçamentária e com os critérios definidos no termo de outorga ou em norma complementar;"}, {"c": "dou-paragraph", "t": "IX - possibilidade de suspensão ou prorrogação da vigência da bolsa em razão de maternidade, adoção ou guarda judicial para fins de adoção, quando aplicável, observadas a legislação específica, as regras do instrumento de fomento, a disponibilidade orçamentária, a compatibilidade com o projeto e as condições previstas no termo de outorga;"}, {"c": "dou-paragraph", "t": "X - interrupção programada das atividades, quando compatível com a duração da bolsa, com o cronograma do projeto e com as entregas pactuadas, conforme previsto no termo de outorga ou autorizado pela unidade executora;"}, {"c": "dou-paragraph", "t": "XI - reconhecimento de sua condição de bolsista em publicações, relatórios, eventos e produtos decorrentes das atividades desenvolvidas, quando houver contribuição efetiva;"}, {"c": "dou-paragraph", "t": "XII - possibilidade de participação em capacitações, treinamentos, atividades de campo, eventos técnico-científicos, ações de difusão tecnológica, publicações e demais atividades formativas ou institucionais relacionadas ao projeto, quando previstas no plano de trabalho, no termo de outorga ou autorizadas pela unidade executora; e"}, {"c": "dou-paragraph", "t": "XIII - observância de condições institucionais compatíveis com a execução respeitosa, segura e adequada das atividades previstas."}, {"c": "dou-paragraph", "t": "§ 1º O seguro contra acidentes pessoais de que trata o inciso VII do caput, quando exigido pela natureza das atividades, deverá ser previsto no plano de trabalho ou no instrumento jurídico aplicável, indicando-se a fonte de custeio e a responsabilidade pela contratação ou comprovação da cobertura."}, {"c": "dou-paragraph", "t": "§ 2º Na hipótese de inexistência de previsão orçamentária específica para contração do seguro de que trata o § 1º, a unidade executora deverá avaliar a necessidade de adequação do plano de trabalho antes do início de atividades que envolvam risco, especialmente em campo ou laboratório."}, {"c": "dou-paragraph", "t": "§ 3º A interrupção programada de que trata o inciso X do caput deverá ser previamente acordada com o supervisor e compatibilizada com o cronograma do projeto, não podendo comprometer entregas essenciais ou atividades críticas."}, {"c": "dou-paragraph", "t": "§ 4º As condições previstas no caput possuem natureza administrativa, protetiva, operacional e organizacional, voltadas à adequada execução do projeto e à mitigação de riscos institucionais, não caracterizando vínculo empregatício, relação funcional, subordinação trabalhista, direito automático a benefícios de natureza laboral ou regime jurídico equiparado ao de servidor público."}, {"c": "dou-paragraph", "t": "CAPÍTULO XI"}, {"c": "dou-paragraph", "t": "DOS DEVERES DO BOLSISTA"}, {"c": "dou-paragraph", "t": "Art. 24. São deveres do bolsista:"}, {"c": "dou-paragraph", "t": "I - executar as atividades previstas no plano individual de atividades com zelo, responsabilidade, assiduidade e qualidade técnica;"}, {"c": "dou-paragraph", "t": "II - cumprir o regime de dedicação ou a carga horária referencial estabelecida, quando houver;"}, {"c": "dou-paragraph", "t": "III - observar as orientações do supervisor ou responsável técnico;"}, {"c": "dou-paragraph", "t": "IV - apresentar relatórios parciais, finais, produtos, registros ou entregas nos prazos definidos;"}, {"c": "dou-paragraph", "t": "V - manter atualizada suas informações cadastrais;"}, {"c": "dou-paragraph", "t": "VI - comunicar imediatamente qualquer fato que possa comprometer a execução das atividades;"}, {"c": "dou-paragraph", "t": "VII - guardar sigilo sobre informações confidenciais, estratégicas, sensíveis ou protegidas a que tiver acesso;"}, {"c": "dou-paragraph", "t": "VIII - observar as normas de biossegurança, segurança do trabalho, integridade científica, ética em pesquisa, proteção de dados, propriedade intelectual e o uso adequado de bens públicos;"}, {"c": "dou-paragraph", "t": "IX - mencionar sua condição de bolsista da CEPLAC, da agência de fomento, da fundação de apoio ou da instituição parceira, conforme o caso, em publicações, apresentações, relatórios ou produtos decorrentes das atividades desenvolvidas;"}, {"c": "dou-paragraph", "t": "X - zelar pelos equipamentos, materiais, documentos, dados, amostras, instalações e bens utilizados no desenvolvimento das atividades;"}, {"c": "dou-paragraph", "t": "XI - restituir valores recebidos indevidamente, quando comprovado descumprimento das condições pactuadas, má-fé, abandono injustificado ou irregularidade na percepção da bolsa;"}, {"c": "dou-paragraph", "t": "XII - não transferir a terceiros as atividades assumidas no plano individual de atividades;"}, {"c": "dou-paragraph", "t": "XIII - não utilizar informações, materiais, dados ou resultados do projeto para finalidade diversa da autorizada; e"}, {"c": "dou-paragraph", "t": "XIV - observar as normas internas da CEPLAC e as disposições do termo de outorga."}, {"c": "dou-paragraph", "t": "Art. 25. O bolsista não poderá acumular bolsas da CEPLAC com bolsas de outras agências nacionais, estrangeiras ou internacionais de fomento ao ensino, pesquisa, desenvolvimento ou inovação, quando houver incompatibilidade de regimes, duplicidade de objeto, sobreposição de dedicação ou vedação no instrumento de fomento, salvo autorização expressa em norma específica ou no instrumento jurídico aplicável."}, {"c": "dou-paragraph", "t": "Parágrafo único. A vedação de acúmulo não impede o recebimento de auxílios, passagens, ressarcimentos, ajuda de custo ou apoios operacionais necessários à execução das atividades, desde que previstos no plano de trabalho, autorizados pela autoridade competente e não configurem duplicidade indevida de pagamento."}, {"c": "dou-paragraph", "t": "Art. 26. A concessão de bolsa a servidor público, empregado público ou agente público envolvido em atividades de pesquisa, desenvolvimento e inovação observará a legislação aplicável, a compatibilidade de horários, a inexistência de prejuízo às atribuições do cargo ou emprego, a autorização da chefia competente, as normas sobre conflito de interesses e as condições previstas no projeto, no plano de trabalho e no termo de outorga."}, {"c": "dou-paragraph", "t": "§ 1º A bolsa concedida a servidor ou empregado público deverá estar diretamente vinculada à execução de atividades de pesquisa, desenvolvimento, inovação, difusão tecnológica ou transferência de tecnologia, vedada sua utilização como complementação remuneratória ordinária."}, {"c": "dou-paragraph", "t": "§ 2º A autorização de que trata o caput deverá ser instruída nos autos do processo administrativo correspondente, sem prejuízo de outras exigências previstas em norma específica."}, {"c": "dou-paragraph", "t": "CAPÍTULO XII"}, {"c": "dou-paragraph", "t": "DAS RESPONSABILIDADES INSTITUCIONAIS"}, {"c": "dou-paragraph", "t": "Art. 27. Compete ao Diretor da CEPLAC:"}, {"c": "dou-paragraph", "t": "I - aprovar as diretrizes gerais para concessão de bolsas;"}, {"c": "dou-paragraph", "t": "II - autorizar, quando necessário, a instituição de modalidades, valores ou procedimentos complementares;"}, {"c": "dou-paragraph", "t": "III - deliberar sobre os casos omissos ou as situações excepcionais; e"}, {"c": "dou-paragraph", "t": "IV - assegurar o alinhamento da política de bolsas às prioridades institucionais da CEPLAC."}, {"c": "dou-paragraph", "t": "Art. 28. Compete à Coordenação-Geral de Pesquisa e Inovação:"}, {"c": "dou-paragraph", "t": "I - coordenar, em articulação com o Núcleo de Inovação Tecnológica da Comissão Executiva do Plano da Lavoura Cacaueira, a implementação do que estabelece esta Portaria;"}, {"c": "dou-paragraph", "t": "II - orientar as unidades da CEPLAC quanto aos procedimentos de concessão, acompanhamento e avaliação das bolsas;"}, {"c": "dou-paragraph", "t": "III - consolidar informações institucionais sobre bolsas vinculadas a projetos de pesquisa, desenvolvimento, inovação e difusão tecnológica;"}, {"c": "dou-paragraph", "t": "IV - propor aperfeiçoamentos normativos; e"}, {"c": "dou-paragraph", "t": "V - apoiar a Diretoria na análise de casos estratégicos ou excepcionais."}, {"c": "dou-paragraph", "t": "Art. 29. Compete ao Núcleo de Inovação Tecnológica:"}, {"c": "dou-paragraph", "t": "I - apoiar tecnicamente a implementação da política institucional de bolsas vinculadas à inovação;"}, {"c": "dou-paragraph", "t": "II - manifestar-se, quando cabível, sobre bolsas relacionadas à propriedade intelectual, transferência de tecnologia, inovação e parcerias estratégicas;"}, {"c": "dou-paragraph", "t": "III - contribuir para a padronização de instrumentos, fluxos e orientações; e"}, {"c": "dou-paragraph", "t": "IV - acompanhar, no âmbito de suas competências, a aderência das bolsas à Política de Inovação da CEPLAC."}, {"c": "dou-paragraph", "t": "Art. 30. Compete às unidades executoras:"}, {"c": "dou-paragraph", "t": "I - elaborar ou instruir os projetos, planos de trabalho e justificativas técnicas;"}, {"c": "dou-paragraph", "t": "II - definir os perfis, os requisitos, as atividades, as modalidades e os critérios de seleção dos bolsistas;"}, {"c": "dou-paragraph", "t": "III - indicar o supervisor ou responsável técnico;"}, {"c": "dou-paragraph", "t": "IV - conduzir ou acompanhar o processo de seleção;"}, {"c": "dou-paragraph", "t": "V - acompanhar a execução das atividades;"}, {"c": "dou-paragraph", "t": "VI - avaliar os relatórios, as entregas e o desempenho;"}, {"c": "dou-paragraph", "t": "VII - informar à Coordenação-Geral de Pesquisa e Inovação, ao Núcleo de Inovação Tecnológica, à fundação de apoio ou à agência de fomento, conforme o caso, situações que justifiquem suspensão, cancelamento, substituição ou prorrogação da bolsa; e"}, {"c": "dou-paragraph", "t": "VIII - manter o registro documental adequado nos autos do processo administrativo."}, {"c": "dou-paragraph", "t": "Art. 31. Compete ao supervisor ou orientador:"}, {"c": "dou-paragraph", "t": "I - orientar o bolsista quanto às atividades previstas;"}, {"c": "dou-paragraph", "t": "II - acompanhar o cumprimento do plano individual de atividades;"}, {"c": "dou-paragraph", "t": "III - avaliar relatórios e entregas;"}, {"c": "dou-paragraph", "t": "IV - comunicar descumprimentos, afastamentos, riscos ou necessidade de ajustes;"}, {"c": "dou-paragraph", "t": "V - atestar, quando cabível, a execução das atividades para fins de manutenção ou pagamento da bolsa; e"}, {"c": "dou-paragraph", "t": "VI - zelar pela aderência das atividades do bolsista aos objetivos do projeto."}, {"c": "dou-paragraph", "t": "Art. 32. Compete à fundação de apoio, agência de fomento ou instituição parceira, quando responsável pela gestão operacional da bolsa:"}, {"c": "dou-paragraph", "t": "I - formalizar o termo de outorga ou instrumento equivalente, quando essa atribuição estiver prevista no instrumento jurídico firmado com a CEPLAC;"}, {"c": "dou-paragraph", "t": "II - realizar o pagamento da bolsa, quando responsável pela gestão financeira dos recursos;"}, {"c": "dou-paragraph", "t": "III - manter registros administrativos e financeiros;"}, {"c": "dou-paragraph", "t": "IV - observar as regras do instrumento jurídico firmado com a CEPLAC;"}, {"c": "dou-paragraph", "t": "V - apoiar a gestão documental e operacional do processo seletivo, quando previsto;"}, {"c": "dou-paragraph", "t": "VI - adotar providências relativas a seguro, auxílios, ressarcimentos e demais despesas autorizadas no plano de trabalho;"}, {"c": "dou-paragraph", "t": "VII - prestar informações à CEPLAC sempre que solicitado;"}, {"c": "dou-paragraph", "t": "VIII - observar a legislação aplicável, inclusive quanto à proteção de dados pessoais, transparência e prestação de contas; e"}, {"c": "dou-paragraph", "t": "IX - observar, quando aplicável, as normas próprias relativas à atuação das fundações de apoio, inclusive quanto aos procedimentos de contratação, transparência, prestação de contas e gestão dos recursos vinculados ao projeto."}, {"c": "dou-paragraph", "t": "CAPÍTULO XIII"}, {"c": "dou-paragraph", "t": "DO ACOMPANHAMENTO, DOS RELATÓRIOS E DA AVALIAÇÃO"}, {"c": "dou-paragraph", "t": "Art. 33. A execução das atividades do bolsista será acompanhada pelo supervisor ou responsável técnico, com base no plano individual de atividades, no cronograma do projeto e nas entregas pactuadas."}, {"c": "dou-paragraph", "t": "Art. 34. O bolsista deverá apresentar relatórios parcial e final, na forma e periodicidade definidas no termo de outorga, no plano de trabalho ou no instrumento de seleção."}, {"c": "dou-paragraph", "t": "§ 1º Recomenda-se, sempre que compatível com a duração da bolsa, a apresentação de relatórios parciais em periodicidade trimestral ou semestral, conforme a natureza do projeto."}, {"c": "dou-paragraph", "t": "§ 2º O relatório final deverá consolidar as atividades desenvolvidas, os resultados alcançados, os produtos gerados, as dificuldades enfrentadas e as contribuições para o projeto."}, {"c": "dou-paragraph", "t": "§ 3º A aprovação dos relatórios pelo supervisor ou responsável técnico constitui requisito para continuidade, renovação ou encerramento regular da bolsa, sem prejuízo de outras exigências previstas no instrumento aplicável."}, {"c": "dou-paragraph", "t": "Art. 35. Poderão ser considerados produtos ou entregas do bolsista, conforme a natureza da atividade:"}, {"c": "dou-paragraph", "t": "I - relatórios técnicos;"}, {"c": "dou-paragraph", "t": "II - artigos, resumos, notas técnicas ou publicações;"}, {"c": "dou-paragraph", "t": "III - bases de dados, planilhas, mapas, registros, diagnósticos ou sistematizações;"}, {"c": "dou-paragraph", "t": "IV - protocolos, metodologias, manuais, guias ou procedimentos;"}, {"c": "dou-paragraph", "t": "V - produtos tecnológicos, processos, softwares, modelos, protótipos ou soluções digitais;"}, {"c": "dou-paragraph", "t": "VI - materiais de difusão tecnológica, capacitação ou comunicação técnica;"}, {"c": "dou-paragraph", "t": "VII - apoio documentado à execução, gestão, monitoramento ou prestação de contas de projetos; e"}, {"c": "dou-paragraph", "t": "VIII - outras entregas previstas no plano individual de atividades."}, {"c": "dou-paragraph", "t": "CAPÍTULO XIV"}, {"c": "dou-paragraph", "t": "DA PROPRIEDADE INTELECTUAL, CONFIDENCIALIDADE E PUBLICAÇÕES"}, {"c": "dou-paragraph", "t": "Art. 36. Os resultados, os dados, as informações, os materiais, as tecnologias, os processos, os produtos, os cultivares, as metodologias, os softwares, os documentos e demais ativos gerados no âmbito das atividades do bolsista observarão as normas de propriedade intelectual, confidencialidade, transferência de tecnologia e inovação aplicáveis à CEPLAC."}, {"c": "dou-paragraph", "t": "Art. 37. O bolsista deverá assinar termo de confidencialidade sempre que tiver acesso a informações estratégicas, sigilosas, sensíveis, protegidas ou potencialmente objeto de propriedade intelectual."}, {"c": "dou-paragraph", "t": "Art. 38. A divulgação de resultados, publicações, apresentações, comunicações técnicas ou materiais decorrentes das atividades desenvolvidas dependerá de anuência do supervisor ou da unidade executora, especialmente quando envolver dados não publicados, informações estratégicas, ativos tecnológicos, propriedade intelectual ou parcerias institucionais."}, {"c": "dou-paragraph", "t": "Art. 39. As publicações e apresentações deverão mencionar a CEPLAC, a fundação de apoio, a agência de fomento ou a instituição parceira, conforme o caso, respeitadas as regras de autoria, contribuição intelectual e reconhecimento institucional."}, {"c": "dou-paragraph", "t": "CAPÍTULO XV"}, {"c": "dou-paragraph", "t": "DAS ATIVIDADES DE CAMPO, DESLOCAMENTO E SEGURANÇA"}, {"c": "dou-paragraph", "t": "Art. 40. Quando as atividades do bolsista envolverem campo, laboratório, unidades experimentais, comunidades rurais, deslocamentos, coleta de amostras, condução de veículos, manipulação de equipamentos ou exposição a riscos, o plano de trabalho deverá prever as condições necessárias à execução segura das atividades."}, {"c": "dou-paragraph", "t": "Art. 41. A condução de veículos por bolsista somente poderá ocorrer quando:"}, {"c": "dou-paragraph", "t": "I - houver necessidade técnica vinculada ao projeto;"}, {"c": "dou-paragraph", "t": "II - a atividade estiver prevista ou autorizada no plano de trabalho ou em documento específico;"}, {"c": "dou-paragraph", "t": "III - o bolsista possuir habilitação válida e compatível;"}, {"c": "dou-paragraph", "t": "IV - houver autorização formal da unidade responsável;"}, {"c": "dou-paragraph", "t": "V - forem observadas as normas de trânsito, segurança e responsabilidade aplicáveis; e"}, {"c": "dou-paragraph", "t": "VI - houver cobertura securitária compatível ou avaliação formal da unidade responsável quanto aos riscos envolvidos, especialmente quando se tratar de veículo oficial, veículo locado ou deslocamento em atividade de campo."}, {"c": "dou-paragraph", "t": "Parágrafo único. A autorização para condução de veículos não caracteriza vínculo funcional, atribuição permanente, subordinação trabalhista ou desvio da finalidade da bolsa, devendo restringir-se às necessidades específicas, temporárias e justificadas do projeto."}, {"c": "dou-paragraph", "t": "Art. 42. As despesas de deslocamento, alimentação, hospedagem, passagens, combustível, seguro, equipamentos de proteção individual e demais custos necessários à execução das atividades somente poderão ser custeados ou ressarcidos quando previstas no plano de trabalho, no termo de outorga ou previamente autorizadas pela autoridade competente, observada a disponibilidade orçamentária e a vinculação direta ao projeto."}, {"c": "dou-paragraph", "t": "CAPÍTULO XVI"}, {"c": "dou-paragraph", "t": "DA SUSPENSÃO, DO CANCELAMENTO, DA SUBSTITUIÇÃO E DO ENCERRAMENTO"}, {"c": "dou-paragraph", "t": "Art. 43. A bolsa poderá ser suspensa, cancelada ou encerrada nas seguintes hipóteses:"}, {"c": "dou-paragraph", "t": "I - término da vigência;"}, {"c": "dou-paragraph", "t": "II - conclusão das atividades previstas;"}, {"c": "dou-paragraph", "t": "III - insuficiência ou encerramento dos recursos do projeto;"}, {"c": "dou-paragraph", "t": "IV - desempenho insatisfatório, devidamente justificado;"}, {"c": "dou-paragraph", "t": "V - descumprimento do plano individual de atividades;"}, {"c": "dou-paragraph", "t": "VI - não apresentação de relatórios ou entregas;"}, {"c": "dou-paragraph", "t": "VII - abandono injustificado das atividades;"}, {"c": "dou-paragraph", "t": "VIII - prestação de informações falsas;"}, {"c": "dou-paragraph", "t": "IX - acúmulo indevido de bolsas;"}, {"c": "dou-paragraph", "t": "X - violação de sigilo de normas de propriedade intelectual, ética, integridade científica ou proteção de dados;"}, {"c": "dou-paragraph", "t": "XI - prática de conduta incompatível com as atividades institucionais;"}, {"c": "dou-paragraph", "t": "XII - por solicitação do bolsista;"}, {"c": "dou-paragraph", "t": "XIII - interesse público devidamente motivado; e"}, {"c": "dou-paragraph", "t": "XIV - outras hipóteses previstas no termo de outorga ou instrumento aplicável."}, {"c": "dou-paragraph", "t": "Art. 44. O cancelamento da bolsa deverá ser precedido de comunicação prévia ao bolsista e de oportunidade para manifestação em prazo razoável, salvo hipóteses de urgência, risco institucional, encerramento do projeto, ausência de recursos, impossibilidade material de continuidade ou situação em que a manutenção da bolsa possa causar prejuízo ao interesse público."}, {"c": "dou-paragraph", "t": "Art. 45. A substituição de bolsista poderá ocorrer mediante justificativa técnica da unidade executora, observados os critérios de seleção aplicáveis e a formalização nos autos do processo."}, {"c": "dou-paragraph", "t": "Art. 46. O encerramento regular da bolsa dependerá da apresentação e aprovação do relatório final ou da comprovação das entregas previstas, salvo impossibilidade justificada."}, {"c": "dou-paragraph", "t": "CAPÍTULO XVII"}, {"c": "dou-paragraph", "t": "DA RESTITUIÇÃO DE VALORES E DA INADIMPLÊNCIA"}, {"c": "dou-paragraph", "t": "Art. 47. Poderá ser exigida a devolução total ou parcial de valores recebidos pelo bolsista, observadas a proporcionalidade, a boa-fé, a extensão do descumprimento e a efetiva apuração dos fatos, quando comprovado:"}, {"c": "dou-paragraph", "t": "I - recebimento indevido;"}, {"c": "dou-paragraph", "t": "II - prestação de informação falsa;"}, {"c": "dou-paragraph", "t": "III - abandono injustificado das atividades;"}, {"c": "dou-paragraph", "t": "IV - descumprimento grave do termo de outorga;"}, {"c": "dou-paragraph", "t": "V - não apresentação de relatórios ou entregas essenciais, sem justificativa aceita;"}, {"c": "dou-paragraph", "t": "VI - acúmulo indevido de bolsas;"}, {"c": "dou-paragraph", "t": "VII - utilização irregular dos recursos; e"}, {"c": "dou-paragraph", "t": "VIII - má-fé ou dolo."}, {"c": "dou-paragraph", "t": "§ 1º A devolução de que trata o caput deverá ser precedida de apuração, motivação e oportunidade de manifestação do interessado."}, {"c": "dou-paragraph", "t": "§ 2º Não será exigida a devolução de valores recebidos pelo bolsista quando o descumprimento decorrer de caso fortuito, força maior, motivo de saúde, maternidade, encerramento antecipado do projeto por interesse da Administração ou outra causa devidamente justificada e aceita pela autoridade competente."}, {"c": "dou-paragraph", "t": "Art. 48. Será considerado inadimplente o bolsista que deixar de cumprir obrigações essenciais previstas nesta Portaria, no termo de outorga, no plano individual de atividades ou no instrumento de seleção, sem justificativa aceita pela unidade responsável."}, {"c": "dou-paragraph", "t": "Parágrafo único. A situação de inadimplência poderá impedir nova concessão de bolsa no âmbito da CEPLAC enquanto não for regularizada a pendência, sem prejuízo de outras medidas cabíveis."}, {"c": "dou-paragraph", "t": "CAPÍTULO XVIII"}, {"c": "dou-paragraph", "t": "DA TRANSPARÊNCIA, CONTROLE E REGISTRO DOCUMENTAL"}, {"c": "dou-paragraph", "t": "Art. 49. Os processos de concessão de bolsas deverão ser instruídos em processo administrativo próprio ou vinculado ao projeto, contendo documentação suficiente para demonstrar a regularidade, motivação, seleção, formalização, execução e encerramento da bolsa."}, {"c": "dou-paragraph", "t": "Art. 50. Deverão constar dos autos, sempre que aplicável:"}, {"c": "dou-paragraph", "t": "I - projeto ou plano de trabalho aprovado;"}, {"c": "dou-paragraph", "t": "II - justificativa técnica da bolsa;"}, {"c": "dou-paragraph", "t": "III - previsão orçamentária;"}, {"c": "dou-paragraph", "t": "IV - instrumento de seleção ou justificativa de seleção específica;"}, {"c": "dou-paragraph", "t": "V - documentação do bolsista;"}, {"c": "dou-paragraph", "t": "VI - termo de outorga;"}, {"c": "dou-paragraph", "t": "VII - plano individual de atividades;"}, {"c": "dou-paragraph", "t": "VIII - relatórios e avaliações;"}, {"c": "dou-paragraph", "t": "IX - registros de pagamento ou informações da entidade gestora;"}, {"c": "dou-paragraph", "t": "X - documentos relativos à prorrogação, suspensão, cancelamento, substituição ou encerramento; e"}, {"c": "dou-paragraph", "t": "XI - demais documentos necessários à rastreabilidade e controle."}, {"c": "dou-paragraph", "t": "Art. 51. A CEPLAC poderá manter cadastro institucional de bolsas concedidas, contendo informações essenciais sobre modalidade, projeto, unidade executora, vigência, valor, fonte de recursos e situação da bolsa, observadas as normas de proteção de dados pessoais."}, {"c": "dou-paragraph", "t": "Art. 52. A publicidade das informações observará a legislação de acesso à informação, proteção de dados pessoais, propriedade intelectual, sigilo industrial, segurança institucional e demais normas aplicáveis."}, {"c": "dou-paragraph", "t": "CAPÍTULO XIX"}, {"c": "dou-paragraph", "t": "DAS VEDAÇÕES"}, {"c": "dou-paragraph", "t": "Art. 53. É vedado:"}, {"c": "dou-paragraph", "t": "I - conceder bolsa sem vinculação a projeto, programa, plano de trabalho ou ação institucional formalmente aprovada;"}, {"c": "dou-paragraph", "t": "II - conceder bolsa sem justificativa técnica e previsão orçamentária;"}, {"c": "dou-paragraph", "t": "III - utilizar bolsa para substituir mão de obra permanente, suprir necessidade ordinária de pessoal ou desempenhar atribuições típicas de cargo efetivo de forma desvinculada de projeto;"}, {"c": "dou-paragraph", "t": "IV - conceder bolsa como contraprestação por serviço administrativo ordinário;"}, {"c": "dou-paragraph", "t": "V - conceder bolsa com finalidade diversa da prevista no projeto ou termo de outorga;"}, {"c": "dou-paragraph", "t": "VI - acumular bolsas em desacordo ao estabelecido nesta Portaria ou em normas do instrumento de fomento;"}, {"c": "dou-paragraph", "t": "VII - iniciar atividades antes da formalização do termo de outorga ou instrumento equivalente;"}, {"c": "dou-paragraph", "t": "VIII - efetuar pagamento sem comprovação mínima da regularidade da concessão;"}, {"c": "dou-paragraph", "t": "IX - utilizar critérios subjetivos, discriminatórios ou não documentados na seleção de bolsistas;"}, {"c": "dou-paragraph", "t": "X - manter bolsista em atividade sem acompanhamento técnico ou plano individual de atividades;"}, {"c": "dou-paragraph", "t": "XI - conceder bolsa em situação que configure nepotismo, conflito de interesses, favorecimento pessoal ou direcionamento indevido;"}, {"c": "dou-paragraph", "t": "XII - utilizar bolsa como complementação remuneratória ordinária de servidor, empregado público ou agente público; e"}, {"c": "dou-paragraph", "t": "XIII - utilizar bolsa para execução de atividade meramente administrativa, contínua ou permanente, sem vinculação direta com projeto de pesquisa, desenvolvimento, inovação, difusão tecnológica ou transferência de tecnologia formalmente aprovado."}, {"c": "dou-paragraph", "t": "CAPÍTULO XX"}, {"c": "dou-paragraph", "t": "DISPOSIÇÕES FINAIS"}, {"c": "dou-paragraph", "t": "Art. 54. A Coordenação-Geral de Pesquisa e Inovação, em articulação com o Núcleo de Inovação Tecnológica, poderá elaborar orientações complementares, modelos de documentos, fluxos procedimentais, minutas de termo de outorga, modelos de plano individual de atividades, relatórios e instrumentos de acompanhamento necessários à implementação desta Portaria."}, {"c": "dou-paragraph", "t": "Art. 55. As unidades da CEPLAC deverão adequar seus projetos, planos de trabalho e instrumentos de parceria ao estabelecido nesta Portaria, especialmente quanto à previsão de bolsas, critérios de seleção, responsabilidades, garantias mínimas, acompanhamento e registro documental."}, {"c": "dou-paragraph", "t": "Art. 56. Os casos omissos serão resolvidos pela Diretoria da CEPLAC, ouvida a Coordenação-Geral de Pesquisa e Inovação e o Núcleo de Inovação Tecnológica e, quando necessário, as unidades técnicas competentes."}, {"c": "dou-paragraph", "t": "Art. 57. Esta Portaria entra em vigor na data de sua publicação."}, {"c": "assina", "t": "THIAGO GUEDES VIANA"}, {"c": "anexo", "t": "ANEXO IDIRETRIZES PARA ENQUADRAMENTO DAS MODALIDADES DE BOLSAS"}, {"c": "dou-paragraph", "t": "O enquadramento das bolsas deverá considerar, de forma combinada, a natureza da atividade, o nível de complexidade, a formação exigida, a experiência profissional, a responsabilidade atribuída, a carga horária ou regime de dedicação e a disponibilidade orçamentária do projeto."}, {"c": "dou-paragraph", "t": "As modalidades de bolsas poderão ser organizadas em níveis, conforme os seguintes parâmetros referenciais:"}, {"c": "dou-paragraph", "t": "I - Iniciação Científica, Tecnológica ou de Inovação: destinada a estudantes de nível médio técnico, graduação ou cursos correlatos, para atividades supervisionadas de iniciação, apoio à pesquisa, levantamento de dados, atividades laboratoriais, campo, difusão tecnológica ou apoio técnico compatível com sua formação;"}, {"c": "dou-paragraph", "t": "II - Apoio Técnico: destinada a profissional de nível médio, técnico ou superior, com experiência compatível, para atividades de suporte técnico, laboratorial, campo, coleta, organização de dados, processamento, apoio operacional qualificado ou execução de procedimentos técnicos, vedada sua utilização para suprir força de trabalho permanente ou demandas ordinárias de pessoal;"}, {"c": "dou-paragraph", "t": "III - Desenvolvimento Tecnológico e Inovação: destinada a profissional de nível superior, especialista, mestre ou doutor, com experiência compatível, para execução de atividades técnico-científicas, desenvolvimento de métodos, produtos, processos, tecnologias, validações ou soluções inovadoras;"}, {"c": "dou-paragraph", "t": "IV - Especialista Visitante: destinada a profissional com experiência reconhecida, cuja participação temporária seja necessária para complementar competências técnicas, científicas, produtivas, gerenciais ou institucionais da equipe do projeto;"}, {"c": "dou-paragraph", "t": "V - Difusão Tecnológica e Extensão Inovadora: destinada a profissional com experiência em comunicação técnica, transferência de tecnologia, validação participativa, capacitação, assistência técnica especializada, demonstração de práticas, sistemas agroflorestais, cacauicultura ou áreas correlatas;"}, {"c": "dou-paragraph", "t": "VI - Tecnologia da Informação, Dados e Sistemas: destinada a profissional com experiência em desenvolvimento de software, sistemas, bancos de dados, geoprocessamento, modelagem, inteligência digital, plataformas tecnológicas, análise de dados ou soluções digitais aplicadas aos projetos da CEPLAC;"}, {"c": "dou-paragraph", "t": "VII - Apoio à Gestão de Projetos de PD&I: destinada a profissional com experiência em gestão, monitoramento, sistematização, planejamento, organização documental, indicadores, relatórios, prestação de contas técnica ou apoio à governança de projetos, desde que as atividades estejam diretamente vinculadas à execução técnica, monitoramento, sistematização, avaliação ou prestação de contas técnica de projeto aprovado, vedada a substituição de atividades administrativas ordinárias da Administração;"}, {"c": "dou-paragraph", "t": "VIII - Pesquisador Visitante ou Sênior: destinada a profissional de elevada qualificação, com trajetória reconhecida e experiência relevante em coordenação, execução, avaliação ou consolidação de projetos científicos, tecnológicos ou de inovação;"}, {"c": "dou-paragraph", "t": "IX - Os valores das bolsas serão definidos em tabela própria da CEPLAC ou em ato específico da Diretoria, podendo adotar como referência tabelas de agências oficiais de fomento, observada a disponibilidade orçamentária e a natureza do projeto;"}, {"c": "dou-paragraph", "t": "X - A tabela de valores deverá ser revisada periodicamente, preferencialmente quando houver atualização das tabelas de referência utilizadas ou quando demonstrada defasagem incompatível com a atração e retenção de profissionais qualificados; e"}, {"c": "dou-paragraph", "t": "XI - O enquadramento em nível superior de bolsa deverá ser acompanhado de justificativa técnica específica, especialmente quando envolver especialista visitante, pesquisador sênior, profissional de notória experiência ou atividade de alta complexidade estratégica."}, {"c": "anexo", "t": "ANEXO II CONTEÚDO MÍNIMO DO PLANO INDIVIDUAL DE ATIVIDADES DO BOLSISTA"}, {"c": "dou-paragraph", "t": "O Plano Individual de Atividades deverá conter, no mínimo:"}, {"c": "dou-paragraph", "t": "I - identificação do bolsista;"}, {"c": "dou-paragraph", "t": "II - identificação do projeto ou programa;"}, {"c": "dou-paragraph", "t": "III - modalidade, nível, valor e vigência da bolsa;"}, {"c": "dou-paragraph", "t": "IV - unidade executora;"}, {"c": "dou-paragraph", "t": "V - supervisor ou orientador responsável;"}, {"c": "dou-paragraph", "t": "VI - objetivo da participação do bolsista;"}, {"c": "dou-paragraph", "t": "VII - descrição detalhada das atividades;"}, {"c": "dou-paragraph", "t": "VIII - produtos, entregas ou resultados esperados;"}, {"c": "dou-paragraph", "t": "IX - cronograma de execução;"}, {"c": "dou-paragraph", "t": "X - carga horária ou regime de dedicação;"}, {"c": "dou-paragraph", "t": "XI - local de execução das atividades;"}, {"c": "dou-paragraph", "t": "XII - necessidade de deslocamentos, atividades de campo, laboratório ou uso de equipamentos;"}, {"c": "dou-paragraph", "t": "XIII - previsão de Equipamento de Proteção Individual - EPI, seguro ou condições especiais de segurança, quando cabível;"}, {"c": "dou-paragraph", "t": "XIV - periodicidade dos relatórios;"}, {"c": "dou-paragraph", "t": "XV - critérios de avaliação;"}, {"c": "dou-paragraph", "t": "XVI - regras de confidencialidade, propriedade intelectual e divulgação de resultados; e"}, {"c": "dou-paragraph", "t": "XVII - assinatura do bolsista, do supervisor e da autoridade responsável."}, {"c": "anexo", "t": "ANEXO III CONTEÚDO MÍNIMO DO TERMO DE OUTORGA"}, {"c": "dou-paragraph", "t": "O Termo de Outorga deverá conter, no mínimo:"}, {"c": "dou-paragraph", "t": "I - qualificação das partes;"}, {"c": "dou-paragraph", "t": "II - identificação do projeto, programa ou ação institucional;"}, {"c": "dou-paragraph", "t": "III - fundamento legal e normativo da concessão;"}, {"c": "dou-paragraph", "t": "IV - modalidade, nível, valor, vigência e fonte de recursos;"}, {"c": "dou-paragraph", "t": "V - forma e periodicidade de pagamento;"}, {"c": "dou-paragraph", "t": "VI - plano individual de atividades;"}, {"c": "dou-paragraph", "t": "VII - carga horária ou regime de dedicação;"}, {"c": "dou-paragraph", "t": "VIII - direitos e deveres do bolsista;"}, {"c": "dou-paragraph", "t": "IX - responsabilidades da CEPLAC, da fundação de apoio, da agência de fomento ou da instituição parceira, conforme o caso;"}, {"c": "dou-paragraph", "t": "X - regras de acompanhamento e apresentação de relatórios;"}, {"c": "dou-paragraph", "t": "XI - cláusula de inexistência de vínculo empregatício;"}, {"c": "dou-paragraph", "t": "XII - cláusula de confidencialidade;"}, {"c": "dou-paragraph", "t": "XIII - cláusula de propriedade intelectual;"}, {"c": "dou-paragraph", "t": "XIV - hipóteses de suspensão, cancelamento, substituição, encerramento e restituição de valores;"}, {"c": "dou-paragraph", "t": "XV - regras sobre afastamentos, recesso, seguro, deslocamentos e condições de segurança, quando aplicáveis;"}, {"c": "dou-paragraph", "t": "XVI - autorização para tratamento de dados pessoais necessários à gestão da bolsa;"}, {"c": "dou-paragraph", "t": "XVII - foro ou instância administrativa competente; e"}, {"c": "dou-paragraph", "t": "XVIII - assinatura das partes."}, {"c": "anexo", "t": "ANEXO IVDIRETRIZES PARA CHAMADA PÚBLICA OU PROCESSO SELETIVO SIMPLIFICADO"}, {"c": "dou-paragraph", "t": "A chamada pública, o edital ou processo seletivo simplificado deverá conter, sempre que aplicável:"}, {"c": "dou-paragraph", "t": "I - identificação da CEPLAC e da unidade executora;"}, {"c": "dou-paragraph", "t": "II - identificação do projeto ou programa;"}, {"c": "dou-paragraph", "t": "III - objeto da seleção;"}, {"c": "dou-paragraph", "t": "IV - número de vagas;"}, {"c": "dou-paragraph", "t": "V - modalidade, nível, valor e vigência da bolsa;"}, {"c": "dou-paragraph", "t": "VI - requisitos mínimos;"}, {"c": "dou-paragraph", "t": "VII - atividades previstas;"}, {"c": "dou-paragraph", "t": "VIII - carga horária ou regime de dedicação;"}, {"c": "dou-paragraph", "t": "IX - local de execução;"}, {"c": "dou-paragraph", "t": "X - documentos exigidos;"}, {"c": "dou-paragraph", "t": "XI - forma e prazo de inscrição;"}, {"c": "dou-paragraph", "t": "XII - etapas da seleção;"}, {"c": "dou-paragraph", "t": "XIII -critérios de avaliação, preferencialmente com pesos ou pontuação;"}, {"c": "dou-paragraph", "t": "XIV - critérios de desempate;"}, {"c": "dou-paragraph", "t": "XV - cronograma;"}, {"c": "dou-paragraph", "t": "XVI - forma de divulgação dos resultados;"}, {"c": "dou-paragraph", "t": "XVII - prazo e forma de interposição de recursos;"}, {"c": "dou-paragraph", "t": "XVIII - condições para convocação e formalização da bolsa;"}, {"c": "dou-paragraph", "t": "XIX - hipóteses de desclassificação;"}, {"c": "dou-paragraph", "t": "XX - disposições sobre confidencialidade, propriedade intelectual e proteção de dados; e"}, {"c": "dou-paragraph", "t": "XXI - informação expressa de que a bolsa não gera vínculo empregatício."}, {"c": "anexo", "t": "ANEXO VDECLARAÇÃO DE NÃO ACÚMULO INDEVIDO DE BOLSA, AUSÊNCIA DE CONFLITO DE INTERESSES E CIÊNCIA DAS CONDIÇÕES DA OUTORGA"}, {"c": "dou-paragraph", "t": "Eu, ____________________________________________, inscrito(a) no CPF nº ________________________, declaro, para os fins de concessão de bolsa no âmbito da Comissão Executiva do Plano da Lavoura Cacaueira - CEPLAC, que não acumulo bolsa em desacordo com as normas aplicáveis, comprometendo-me a comunicar imediatamente qualquer alteração superveniente que possa configurar acúmulo indevido."}, {"c": "dou-paragraph", "t": "Declaro, ainda, não me encontrar em situação de conflito de interesses, nepotismo, impedimento ou incompatibilidade que comprometa a regularidade, a impessoalidade ou a moralidade da concessão da bolsa, comprometendo-me a comunicar imediatamente qualquer alteração superveniente."}, {"c": "dou-paragraph", "t": "Declaro estar ciente de que a bolsa não gera vínculo empregatício, funcional, estatutário ou contratual de prestação de serviços, nem constitui salário, remuneração ordinária ou complementação remuneratória."}, {"c": "dou-paragraph", "t": "Declaro estar ciente de que a prestação de informação falsa poderá acarretar o cancelamento da bolsa, a restituição de valores recebidos indevidamente e a adoção das medidas administrativas cabíveis."}, {"c": "dou-paragraph", "t": "Local e data: ___________________________________"}, {"c": "dou-paragraph", "t": "Assinatura: ____________________________________"}]});